// stray.jsx — Koroze bludnými proudy (stray-current corrosion)
// DC systémy (tramvaje, metro): trakční proud se má vracet kolejnicemi do
// měnírny, ale část uniká do země, vstupuje do uloženého potrubí a putuje jím.
// Tam, kde proud VYSTUPUJE z kovu do půdy (anodické místo), kov koroduje.
// Načítá se společně s ../../animations.jsx (Stage, useTime, clamp).

const easeIO = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);
function fade(t, a, b, c, d) {
  if (t <= a || t >= d) return 0;
  if (t < b) return clamp((t - a) / (b - a), 0, 1);
  if (t < c) return 1;
  return 1 - clamp((t - c) / (d - c), 0, 1);
}
function prog(t, a, b) { return easeIO(clamp((t - a) / (b - a), 0, 1)); }

// deterministické pity v korozní zóně
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function makePits(seed, count, spread, rmax) {
  const r = mulberry32(seed);
  return Array.from({ length: count }, () => ({
    dx: (r() * 2 - 1) * spread,
    r: rmax * (0.5 + r() * 0.5),
    ph: r(),
  }));
}
const RAIL_PITS = makePits(11, 7, 78, 11);
const PIPE_PITS = makePits(29, 7, 74, 11);

// geometrie
const WIRE_Y = 440;
const SUB_X = 435;           // svislá osa měnírny / trolejového svodu
const RAIL_TOP = 590, RAIL_MID = 598, RAIL_BOT = 606;
const PIPE_TOP = 900, PIPE_MID = 918, PIPE_BOT = 940;
const PANTO_X = 1603;        // špička pantografu na obrázku šaliny (vpravo, zrcadleno)
// šalina (PNG 824×184), kola dosedají na kolejnici
const TRAM_W = 720, TRAM_H = TRAM_W * 184 / 824;
const TRAM_L = 1005, TRAM_B = 596, TRAM_T = TRAM_B - TRAM_H;
const TRAM_SRC = 'data:image/png;base64,';
const RAIL_ZONE_X = 1603;    // pod trolejí — proud jde rovně dolů ke kolejnici i potrubí
const PIPE_EXIT_X = 460;     // kde proud vystupuje z potrubí → koroze potrubí

const TEMPO_DUR = { 'Klidné': 37, 'Standardní': 29, 'Rychlé': 23 };

function Scene({ tempo = 'Standardní' } = {}) {
  const t = useTime();
  const mono = "'IBM Plex Mono', monospace";
  const sans = "'IBM Plex Sans', system-ui, sans-serif";
  const k = (TEMPO_DUR[tempo] || 29) / 29;
  const T = (x) => x * k;

  const CURR = 'oklch(0.8 0.13 235)';    // trakční proud (modrá)
  const STRAY = 'oklch(0.83 0.15 82)';   // bludný proud (jantarová)
  const WARM = 'oklch(0.7 0.18 32)';     // koroze (červenooranžová)
  const GOOD = 'oklch(0.75 0.13 155)';   // chráněno / katoda (zelená)
  const STEEL_LINE = 'oklch(0.72 0.02 250)';
  const MUTE = '#8296a8';

  const appear = prog(t, T(0.4), T(1.8));
  const DY = -140; // posun celé scény, aby byla vertikálně ve středu obrazovky

  const supplyOn = prog(t, T(2.0), T(3.2));
  const returnOn = prog(t, T(6.0), T(7.2));
  const strayDown = prog(t, T(9.5), T(10.8));
  const strayPipe = prog(t, T(12.5), T(13.8));
  const strayUp = prog(t, T(15.5), T(16.8));

  const corRail = prog(t, T(16.8), T(21));
  const corPipe = prog(t, T(17.2), T(21.5));
  const cathodeOn = prog(t, T(20.5), T(22));
  const glow = 0.55 + 0.45 * Math.sin(t * 2.6);

  // ── easter egg: krokodýl (T(23) → konec) ──
  const crocScale = prog(t, T(23.0), T(23.6));
  const crocClimb = prog(t, T(23.0), T(24.9));
  const crocWalk = prog(t, T(24.9), T(27.6));
  const crocBoard = prog(t, T(27.6), T(28.5));
  const CROC_DOOR_X = 1150;
  const crocOp = crocScale > 0 ? 1 - crocBoard : 0;
  let crocX = PIPE_EXIT_X + crocWalk * (CROC_DOOR_X - PIPE_EXIT_X);
  let crocY = crocWalk > 0
    ? RAIL_TOP - 1 - (crocWalk < 1 ? Math.abs(Math.sin(t * 9)) * 4 : 0)
    : 902 - crocClimb * (902 - (RAIL_TOP - 1));
  const crocRot = -90 + Math.min(crocWalk * 3, 1) * 90;
  if (crocBoard > 0) { crocX += crocBoard * 36; crocY -= crocBoard * 26; }
  const legSwing = (crocWalk > 0 && crocWalk < 1) ? Math.sin(t * 9) * 8 : 0;

  // marching-ants posun (kladný t → posun ve směru kreslení cesty)
  const off = (speed) => -(t * speed);

  // paths (kresleny VE SMĚRU toku proudu)
  const P_SUPPLY = `M${SUB_X} 470 L${SUB_X} ${WIRE_Y} L${PANTO_X} ${WIRE_Y} L${PANTO_X} ${RAIL_TOP}`;
  const P_RETURN = `M${RAIL_ZONE_X + 160} ${RAIL_MID} L${SUB_X} ${RAIL_MID} L${SUB_X} 520`;
  const P_DOWN = `M${RAIL_ZONE_X} ${RAIL_BOT} L${RAIL_ZONE_X} ${PIPE_TOP}`;
  const P_PIPE = `M${RAIL_ZONE_X} ${PIPE_MID} L${PIPE_EXIT_X} ${PIPE_MID}`;
  const P_UP = `M${PIPE_EXIT_X} ${PIPE_TOP} L${PIPE_EXIT_X} ${RAIL_BOT}`;

  const flow = (d, opacity, color, width, speed, dash = '13 12') => (
    opacity > 0.001 ? (
      <path d={d} fill="none" stroke={color} strokeWidth={width} opacity={opacity}
        strokeLinecap="round" strokeDasharray={dash} strokeDashoffset={off(speed)} />
    ) : null
  );

  // arrowhead na konci cesty (ukazuje směr proudu)
  const arrow = (x, y, dir, color, op) => {
    if (op < 0.02) return null;
    const s = 13;
    const pts = dir === 'down' ? `${x - s},${y - s} ${x + s},${y - s} ${x},${y}`
      : dir === 'up' ? `${x - s},${y + s} ${x + s},${y + s} ${x},${y}`
      : dir === 'left' ? `${x + s},${y - s} ${x + s},${y + s} ${x},${y}`
      : `${x - s},${y - s} ${x - s},${y + s} ${x},${y}`;
    return <polygon points={pts} fill={color} opacity={op} />;
  };

  // rising corrosion particles
  const particles = (cx, yBase, dirUp, amount, color) => {
    if (amount < 0.02) return null;
    const n = 5, span = 60, per = 1.6;
    return Array.from({ length: n }, (_, i) => {
      const ph = ((t / per) + i / n) % 1;
      const y = dirUp ? yBase - ph * span : yBase + ph * span;
      const x = cx + (i - 2) * 16 + Math.sin(t * 2 + i) * 5;
      return <circle key={i} cx={x} cy={y} r={2.6} fill={color}
        opacity={amount * (1 - ph) * 0.9} />;
    });
  };

  return (
    <div style={{ position: 'absolute', inset: 0 }}>
      <div style={{ position: 'absolute', inset: 0,
        background: 'radial-gradient(120% 90% at 50% 34%, rgba(30,52,80,0.4) 0%, rgba(9,13,20,0) 62%)' }} />

      <svg width={1920} height={1080} style={{ position: 'absolute', inset: 0 }}>
        <defs>
          <linearGradient id="soil" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="oklch(0.27 0.018 250)" />
            <stop offset="1" stopColor="oklch(0.15 0.012 250)" />
          </linearGradient>
          <linearGradient id="steel" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="oklch(0.5 0.02 250)" />
            <stop offset="0.5" stopColor="oklch(0.68 0.02 250)" />
            <stop offset="1" stopColor="oklch(0.4 0.02 250)" />
          </linearGradient>
          <linearGradient id="tram" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="oklch(0.34 0.02 250)" />
            <stop offset="1" stopColor="oklch(0.22 0.015 250)" />
          </linearGradient>
          <filter id="glow" x="-60%" y="-60%" width="220%" height="220%">
            <feGaussianBlur stdDeviation="6" result="b" />
            <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
        </defs>

        <g opacity={appear} transform={`translate(0 ${DY})`}>
          {/* půda */}
          <rect x={0} y={RAIL_TOP} width={1920} height={1080 - RAIL_TOP + Math.abs(DY)} fill="url(#soil)" />
          <line x1={0} y1={RAIL_TOP} x2={1920} y2={RAIL_TOP} stroke="oklch(0.42 0.02 250)" strokeWidth={1.5} />

          {/* trolejové vedení */}
          <line x1={280} y1={WIRE_Y} x2={1740} y2={WIRE_Y} stroke={STEEL_LINE} strokeWidth={3} />
          <text x={620} y={WIRE_Y - 16} fontFamily={mono} fontSize={19} fill={MUTE} letterSpacing="0.04em">Trolejové vedení</text>
          <text x={SUB_X + 20} y={WIRE_Y - 14} fontFamily={mono} fontSize={30} fontWeight="600" fill={CURR}>+</text>

          {/* měnírna */}
          <line x1={SUB_X} y1={470} x2={SUB_X} y2={WIRE_Y} stroke={STEEL_LINE} strokeWidth={3} />
          <line x1={SUB_X} y1={586} x2={SUB_X} y2={RAIL_TOP} stroke={STEEL_LINE} strokeWidth={3} />
          <rect x={SUB_X - 82} y={470} width={164} height={116} rx={6} fill="url(#tram)" stroke={STEEL_LINE} strokeWidth={2} />
          <text x={SUB_X} y={524} textAnchor="middle" fontFamily={mono} fontSize={20} fill="#cdd8e4">Měnírna</text>
          <text x={SUB_X} y={548} textAnchor="middle" fontFamily={mono} fontSize={14} fill={MUTE}>usměrňovač</text>
          <text x={SUB_X - 44} y={566} fontFamily={mono} fontSize={30} fontWeight="600" fill={CURR}>−</text>

          {/* kolejnice */}
          <rect x={0} y={RAIL_TOP} width={1920} height={RAIL_BOT - RAIL_TOP} fill="url(#steel)" />
          <text x={40} y={RAIL_TOP - 16} fontFamily={mono} fontSize={19} fill={MUTE}>Kolejnice</text>

          {/* potrubí */}
          <rect x={0} y={PIPE_TOP} width={1920} height={PIPE_BOT - PIPE_TOP} fill="url(#steel)" />
          <rect x={0} y={PIPE_TOP} width={1920} height={5} fill="oklch(0.8 0.02 250 / 0.5)" />
          <text x={40} y={PIPE_TOP - 18} fontFamily={mono} fontSize={19} fill={MUTE}>Inženýrské sítě — potrubí</text>

          {/* tramvaj (šalina) */}
          <image href={TRAM_SRC} x={TRAM_L} y={TRAM_T} width={TRAM_W} height={TRAM_H} preserveAspectRatio="xMidYMid meet" />

          {/* ── PROUDY ── */}
          <g filter="url(#glow)">
            {flow(P_SUPPLY, supplyOn, CURR, 4, 42)}
            {flow(P_RETURN, returnOn, CURR, 4, 42)}
            {flow(P_DOWN, strayDown, STRAY, 3.4, 34, '11 12')}
            {flow(P_PIPE, strayPipe, STRAY, 3.4, 34, '11 12')}
            {flow(P_UP, strayUp, STRAY, 3.4, 34, '11 12')}
          </g>
          {arrow(PANTO_X, RAIL_TOP, 'down', CURR, supplyOn)}
          {arrow(SUB_X, 508, 'up', CURR, returnOn)}
          {arrow(RAIL_ZONE_X, PIPE_TOP - 4, 'down', STRAY, strayDown)}
          {arrow(PIPE_EXIT_X + 8, PIPE_MID, 'left', STRAY, strayPipe)}
          {arrow(PIPE_EXIT_X, RAIL_BOT - 2, 'up', STRAY, strayUp)}

          {/* ── KOROZE kolejnice (proud vystupuje z kovu) ── */}
          <g>
            {RAIL_PITS.map((p, i) => {
              const rr = p.r * corRail;
              return <circle key={i} cx={RAIL_ZONE_X + p.dx} cy={RAIL_BOT} r={rr}
                fill="oklch(0.13 0.012 250)" stroke={WARM} strokeWidth={1.6} opacity={corRail} />;
            })}
            <circle cx={RAIL_ZONE_X} cy={RAIL_BOT + 4} r={70 * corRail} fill={WARM}
              opacity={corRail * glow * 0.16} />
            {particles(RAIL_ZONE_X, RAIL_BOT + 8, false, corRail, WARM)}
          </g>

          {/* ── KOROZE potrubí (proud vystupuje z kovu) ── */}
          <g>
            {PIPE_PITS.map((p, i) => {
              const rr = p.r * corPipe;
              return <circle key={i} cx={PIPE_EXIT_X + p.dx} cy={PIPE_TOP} r={rr}
                fill="oklch(0.13 0.012 250)" stroke={WARM} strokeWidth={1.6} opacity={corPipe} />;
            })}
            <circle cx={PIPE_EXIT_X} cy={PIPE_TOP} r={70 * corPipe} fill={WARM}
              opacity={corPipe * glow * 0.16} />
            {particles(PIPE_EXIT_X, PIPE_TOP - 8, true, corPipe, WARM)}
          </g>

          {/* ── katodická (chráněná) místa: kam proud VSTUPUJE ── */}
          <g opacity={cathodeOn}>
            <circle cx={RAIL_ZONE_X} cy={PIPE_TOP} r={9} fill="none" stroke={GOOD} strokeWidth={2.5} />
            <circle cx={PIPE_EXIT_X - 4} cy={0} r={0} />
            <circle cx={SUB_X + 0} cy={0} r={0} />
            <text x={RAIL_ZONE_X + 20} y={PIPE_TOP - 12} fontFamily={mono} fontSize={15} fill={GOOD}>katoda — chráněno</text>
          </g>

          {/* ── easter egg: krokodýl vylézá z koroze a stíhá šalinu ── */}
          {crocOp > 0.01 ? (
            <g transform={`translate(${crocX} ${crocY}) rotate(${crocRot}) scale(${crocScale})`} opacity={crocOp}>
              {/* ocas */}
              <path d="M-28 -14 Q-56 -12 -72 -2 Q-54 -4 -28 -3 Z" fill="oklch(0.52 0.12 145)" />
              {/* nohy */}
              <g stroke="oklch(0.44 0.1 145)" strokeWidth={5} strokeLinecap="round">
                <line x1={-14} y1={-8} x2={-14 + legSwing} y2={0} />
                <line x1={12} y1={-8} x2={12 - legSwing} y2={0} />
              </g>
              {/* tělo */}
              <ellipse cx={0} cy={-14} rx={32} ry={11} fill="oklch(0.58 0.13 145)" />
              {/* hřbetní zuby */}
              <path d="M-26 -23 l5 -6 l5 6 l5 -6 l5 6 l5 -6 l5 6 Z" fill="oklch(0.46 0.12 145)" />
              {/* hlava + tlama */}
              <path d="M22 -22 Q42 -25 58 -16 Q61 -13 56 -11 L26 -8 Z" fill="oklch(0.58 0.13 145)" />
              <path d="M32 -11 l4 3 l4 -3 l4 3 l4 -3 l4 3" fill="none" stroke="#fff" strokeWidth={1.4} />
              {/* oko */}
              <circle cx={31} cy={-21} r={3.4} fill="#fff" />
              <circle cx={32} cy={-21} r={1.6} fill="#111" />
            </g>
          ) : null}
        </g>
      </svg>

      {/* korozní štítky */}
      {corRail > 0.4 ? (
        <div style={{ position: 'absolute', left: (RAIL_ZONE_X + 24) / 1920 * 100 + '%', top: (RAIL_BOT + 26 + DY) / 1080 * 100 + '%', opacity: corRail }}>
          <div style={{ fontFamily: mono, fontSize: 17, fontWeight: 600, color: '#ff9a6b' }}>KOROZE kolejnice</div>
          <div style={{ fontFamily: mono, fontSize: 13, color: MUTE }}>anoda · úbytek kovu</div>
        </div>
      ) : null}
      {corPipe > 0.4 ? (
        <div style={{ position: 'absolute', left: (PIPE_EXIT_X + 26) / 1920 * 100 + '%', top: (PIPE_TOP - 66 + DY) / 1080 * 100 + '%', opacity: corPipe }}>
          <div style={{ fontFamily: mono, fontSize: 17, fontWeight: 600, color: '#ff9a6b' }}>KOROZE potrubí</div>
          <div style={{ fontFamily: mono, fontSize: 13, color: MUTE }}>anoda · úbytek kovu</div>
        </div>
      ) : null}

      {/* titulek */}
      <div style={{ position: 'absolute', left: 84, top: 74, opacity: fade(t, T(0.2), T(0.9), 400, 401) }}>
        <div style={{ fontFamily: mono, fontSize: 18, letterSpacing: '0.28em', color: '#f0b36a', textTransform: 'uppercase' }}>Koroze · Bludné proudy</div>
        <div style={{ fontFamily: sans, fontSize: 40, fontWeight: 600, color: '#eaf2fa', marginTop: 10, letterSpacing: '-0.01em' }}>Koroze bludnými proudy</div>
      </div>

      {/* postupné popisky dole */}
      {[
        { n: '01', txt: 'Šalina odebírá trakční proud (+) z trolejového vedení', a: T(2.2), b: T(2.9), c: T(5.7), d: T(6.2) },
        { n: '02', txt: 'Většina proudu se vrací kolejnicemi zpět do měnírny (−)', a: T(6.2), b: T(6.9), c: T(9.2), d: T(9.7) },
        { n: '03', txt: 'Část proudu uniká z kolejnice do vlhké půdy — bludný proud', a: T(9.7), b: T(10.4), c: T(12.2), d: T(12.7) },
        { n: '04', txt: 'Bludný proud vstupuje do potrubí a protéká jím k měnírně', a: T(12.7), b: T(13.4), c: T(15.4), d: T(15.9) },
        { n: '05', txt: 'Kde proud vystupuje z kovu do půdy, kov koroduje (anoda)', a: T(15.9), b: T(16.6), c: T(20.6), d: T(21.1) },
        { n: '06', txt: 'Napadeno je proto potrubí i kolejnice — v místech výstupu proudu', a: T(21.1), b: T(21.8), c: T(200), d: T(201) },
      ].map((s, i) => {
        const o = fade(t, s.a, s.b, s.c, s.d);
        if (o < 0.001) return null;
        return (
          <div key={i} style={{ position: 'absolute', left: '50%', bottom: 88,
            transform: `translate(-50%, ${(1 - o) * 10}px)`, opacity: o, textAlign: 'center', width: 1200 }}>
            <div style={{ fontFamily: mono, fontSize: 16, letterSpacing: '0.24em', color: '#f0b36a', marginBottom: 12 }}>{s.n}</div>
            <div style={{ fontFamily: sans, fontSize: 33, fontWeight: 500, color: '#eaf2fa', letterSpacing: '-0.005em' }}>{s.txt}</div>
          </div>
        );
      })}
    </div>
  );
}

function StrayAnimation(props) {
  props = props || {};
  const tempo = props.tempo || 'Standardní';
  return (
    <Stage width={1920} height={1080} duration={TEMPO_DUR[tempo] || 29} background="#080b12" persistKey="stray-bludne-proudy" loop={false}>
      <Scene tempo={tempo} />
    </Stage>
  );
}

window.StrayAnimation = StrayAnimation;
